require __DIR__.'/includes/bootstrap.php';require_permission('account.access');$pdo=db();$user=current_user();if(!$pdo||!$user)redirect(url('/login.php'));vp3_connected_sites_ensure_schema_v100($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf()){flash('error','Session expired. Please try again.');redirect(url('/connected-sites.php'));}try{$id=(int)($_POST['connection_id']??0);vp3_connected_site_revoke_v100($pdo,(int)$user['id'],$id);flash('notice','Connected site disconnected. Future access has been revoked.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect(url('/connected-sites.php'));}
