?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VP3 | Connected Sites</title><link rel="stylesheet" href="<?=e(url('/chat.css?v=82'))?>"><link rel="stylesheet" href="<?=e(url('/account.css?v=account-light-20260904'))?>"></head><body><div class="chat-app"><?php $workspaceSidebarUser=$user;$workspaceSidebarActive='account';require __DIR__.'/includes/workspace-sidebar-v82.php';?><div class="chat-sidebar-backdrop" id="chatSidebarBackdrop"></div><main class="chat-main"><?php require __DIR__.'/includes/member-header.php';?><section class="account-canvas"><div class="account-canvas-inner"><section class="account-panel"><div class="account-panel-head"><span>Security & access</span><h1>Connected Sites</h1><p>These sites have been explicitly authorized to access selected VP3 account data. Revoke any connection you no longer use.</p></div><?php if($n=flash('notice')):?><div class="account-alert success"><?=e($n)?></div><?php endif?><?php if($e=flash('error')):?><div class="account-alert error"><?=e($e)?></div><?php endif?><div style="display:grid;gap:12px"><?php if(!$rows):?><div class="account-alert">No external sites are connected to this VP3 account.</div><?php endif?><?php foreach($rows as $row):?><article style="border:1px solid #e1e3e8;border-radius:16px;padding:18px;display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center"><div><strong style="font-size:1.05rem"><?=e((string)$row['app_label'])?></strong><div style="color:#666;margin-top:4px"><?=e(ucfirst((string)$row['status']))?> · Connected <?=e((string)$row['connected_at'])?><?=!empty($row['last_used_at'])?' · Last used '.e((string)$row['last_used_at']):''?></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px"><?php foreach($row['scopes'] as $scope):?><span style="background:#f1f2f4;padding:5px 8px;border-radius:99px;font-size:12px"><?=e((string)$scope)?></span><?php endforeach?></div></div><?php if($row['status']==='active'):?><form method="post" onsubmit="return confirm('Disconnect <?=e((string)$row['app_label'])?> from your VP3 account?')"><?=csrf_field()?><input type="hidden" name="connection_id" value="<?=(int)$row['id']?>"><button class="account-shell-button" type="submit">Disconnect</button></form><?php else:?><span>Revoked</span><?php endif?></article><?php endforeach?></div></section></div></section></main></div></body></html>